 * Cell address helpers: column/letter conversion, address parsing, ordering.
 */

const ADDRESS_RE = /^([A-Z]{1,2})([0-9]{1,3})$/

/**
 * Convert a 1-2 letter column name into its 1-based number (A=1 .. Z=26,
 * AA=27 .. ZZ=702).
 */
export function lettersToCol(letters) {
  let n = 0
  for (const ch of letters) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

/** Inverse of lettersToCol, for column numbers 1..702. */
export function colToLetters(num) {
  if (num <= 26) return String.fromCharCode(64 + num)
  const n2 = num - 26
  const first = Math.floor((n2 - 1) / 26) + 1
  const second = ((n2 - 1) % 26) + 1
  return String.fromCharCode(64 + first) + String.fromCharCode(64 + second)
}

/**
 * Parse a token (case-insensitively) as a cell address. Returns
 * { col, row } on success, or null if the token is not one or two letters
 * followed by one to three digits naming a row of at least 1.
 */
export function parseAddress(token) {
  const m = ADDRESS_RE.exec(token.toUpperCase())
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  return { col: lettersToCol(m[1]), row }
}

/** Canonical "A1"-style string for a { col, row } pair. */
export function addressKey(col, row) {
  return colToLetters(col) + String(row)
}

/** Ascending column-then-row comparator for { col, row } pairs. */
export function compareColRow(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}
"}

