 * Tokenizer for formula bodies (the part of a cell's content after the
 * leading '=').
 */

export class LexError extends Error {}

const TWO_CHAR_OPS = ['<=', '>=', '<>']
const ONE_CHAR_OPS = new Set(['<', '>', '=', '^', '*', '/', '+', '-', '(', ')', ':', ','])

/**
 * Turn a formula body into a token list. Each token is
 * { type, value } where type is one of 'num', 'word', 'op', or a literal
 * punctuation type equal to its text ('(', ')', ':', ',').
 * Throws LexError on any character that cannot start a token.
 */
export function tokenize(text) {
  const tokens = []
  let i = 0
  const n = text.length
  while (i < n) {
    const ch = text[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    const two = text.slice(i, i + 2)
    if (TWO_CHAR_OPS.includes(two)) {
      tokens.push({ type: 'op', value: two })
      i += 2
      continue
    }
    if (/[0-9]/.test(ch)) {
      const m = /^[0-9]+(\.[0-9]+)?/.exec(text.slice(i))
      tokens.push({ type: 'num', value: m[0] })
      i += m[0].length
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      const m = /^[A-Za-z]+[0-9]*/.exec(text.slice(i))
      tokens.push({ type: 'word', value: m[0] })
      i += m[0].length
      continue
    }
    if (ONE_CHAR_OPS.has(ch)) {
      if (ch === '(' || ch === ')' || ch === ':' || ch === ',') {
        tokens.push({ type: ch, value: ch })
      } else {
        tokens.push({ type: 'op', value: ch })
      }
      i++
      continue
    }
    throw new LexError(`unexpected character ${ch}`)
  }
  return tokens
}
"}

