{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-sMfGFe/src/parser.js","content":"/**
 * Recursive-descent parser for formula bodies, producing an AST or
 * reporting that the grammar does not accept the text.
 */

import { tokenize, LexError } from './lexer.js'
import { parseAddress } from './address.js'

export class ParseFail extends Error {}

const FUNCTION_NAMES = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])
const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class Cursor {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }
  peek() {
    return this.tokens[this.pos]
  }
  next() {
    return this.tokens[this.pos++]
  }
  expect(type) {
    const t = this.next()
    if (!t || t.type !== type) throw new ParseFail(`expected ${type}`)
    return t
  }
  atEnd() {
    return this.pos >= this.tokens.length
  }
}

function parsePrimary(c) {
  const t = c.peek()
  if (!t) throw new ParseFail('unexpected end of input')
  if (t.type === 'num') {
    c.next()
    return { type: 'num', value: Number(t.value) }
  }
  if (t.type === '(') {
    c.next()
    const inner = parseComparison(c)
    c.expect(')')
    return inner
  }
  if (t.type === 'word') {
    c.next()
    const upper = t.value.toUpperCase()
    const nxt = c.peek()
    if (nxt && nxt.type === '(') {
      return parseCall(c, upper)
    }
    if (upper === 'TRUE') return { type: 'bool', value: true }
    if (upper === 'FALSE') return { type: 'bool', value: false }
    const addr = parseAddress(t.value)
    return { type: 'addr', valid: addr !== null, col: addr ? addr.col : null, row: addr ? addr.row : null }
  }
  throw new ParseFail('unexpected token')
}

function parseCall(c, name) {
  c.expect('(')
  const args = []
  args.push(parseArgument(c))
  while (c.peek() && c.peek().type === ',') {
    c.next()
    args.push(parseArgument(c))
  }
  c.expect(')')
  return { type: 'call', name, args }
}

function parseArgument(c) {
  const t0 = c.peek()
  const t1 = c.tokens[c.pos + 1]
  const t2 = c.tokens[c.pos + 2]
  if (t0 && t0.type === 'word' && t1 && t1.type === ':' && t2 && t2.type === 'word') {
    // Only treat as a range if neither word is immediately a function call
    // or boolean keyword use; a plain range is two bare words joined by ':'.
    c.next()
    c.next()
    c.next()
    const from = parseAddress(t0.value)
    const to = parseAddress(t2.value)
    return { type: 'range', from, to }
  }
  return parseComparison(c)
}

function parseUnary(c) {
  const t = c.peek()
  if (t && t.type === 'op' && (t.value === '-' || t.value === '+')) {
    c.next()
    const expr = parseUnary(c)
    return { type: 'unary', op: t.value, expr }
  }
  return parsePrimary(c)
}

function parsePower(c) {
  const left = parseUnary(c)
  const t = c.peek()
  if (t && t.type === 'op' && t.value === '^') {
    c.next()
    const right = parsePower(c)
    return { type: 'binop', op: '^', left, right }
  }
  return left
}

function parseMultiplicative(c) {
  let left = parsePower(c)
  for (;;) {
    const t = c.peek()
    if (t && t.type === 'op' && (t.value === '*' || t.value === '/')) {
      c.next()
      const right = parsePower(c)
      left = { type: 'binop', op: t.value, left, right }
    } else break
  }
  return left
}

function parseAdditive(c) {
  let left = parseMultiplicative(c)
  for (;;) {
    const t = c.peek()
    if (t && t.type === 'op' && (t.value === '+' || t.value === '-')) {
      c.next()
      const right = parseMultiplicative(c)
      left = { type: 'binop', op: t.value, left, right }
    } else break
  }
  return left
}

function parseComparison(c) {
  let left = parseAdditive(c)
  for (;;) {
    const t = c.peek()
    if (t && t.type === 'op' && COMPARISON_OPS.has(t.value)) {
      c.next()
      const right = parseAdditive(c)
      left = { type: 'binop', op: t.value, left, right }
    } else break
  }
  return left
}

/**
 * Parse a formula body (text after the leading '='). Returns
 * { ok: true, ast } on success or { ok: false } if the grammar rejects it.
 */
export function parseFormula(text) {
  try {
    const tokens = tokenize(text)
    const c = new Cursor(tokens)
    const ast = parseComparison(c)
    if (!c.atEnd()) throw new ParseFail('trailing tokens')
    return { ok: true, ast }
  } catch (e) {
    if (e instanceof ParseFail || e instanceof LexError) return { ok: false }
    throw e
  }
}

export { FUNCTION_NAMES }
"}

