export const NUMBER = (value) => ({ type: 'number', value })
export const TEXT = (value) => ({ type: 'text', value })
export const BOOL = (value) => ({ type: 'bool', value })
export const ERROR = (value) => ({ type: 'error', value })

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

/** Parse literal cell content (anything not starting with '=') into a value. */
export function parseLiteral(content) {
  if (content === '') return NUMBER(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return NUMBER(Number(content))
  if (ERROR_TOKENS.includes(content)) return ERROR(content)
  return TEXT(content)
}

/** Read a value as a number for arithmetic; text becomes #VALUE!. */
export function toNumberForArithmetic(v) {
  if (v.type === 'number') return v
  if (v.type === 'bool') return NUMBER(v.value ? 1 : 0)
  if (v.type === 'text') return ERROR('#VALUE!')
  return v // error passthrough
}

/** Read a value as a condition; text becomes #VALUE!. */
export function toBoolean(v) {
  if (v.type === 'bool') return v
  if (v.type === 'number') return BOOL(v.value !== 0)
  if (v.type === 'text') return ERROR('#VALUE!')
  return v // error passthrough
}

/** Rank for cross-kind comparison: number < text < bool. */
function kindRank(v) {
  if (v.type === 'number') return 0
  if (v.type === 'text') return 1
  return 2
}

/** Compare two non-error values per the spec's comparison rules. */
export function compareValues(a, b) {
  const ra = kindRank(a)
  const rb = kindRank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (a.type === 'number') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  if (a.type === 'text') return a.value < b.value ? -1 : a.value > b.value ? 1 : 0
  const av = a.value ? 1 : 0
  const bv = b.value ? 1 : 0
  return av < bv ? -1 : av > bv ? 1 : 0
}

/** Round to ten significant digits and print as JavaScript would. */
export function formatNumber(x) {
  if (x === 0) return '0'
  const rounded = Number(x.toPrecision(10))
  return String(rounded)
}

